#!/usr/bin/env python3
"""Bootstrap CIs for aggregation method R² (Table 2).

Uses EXACT same ASR computation as run_aggregation_loglog.py:
- EPS=1e-6, OLS log-log with standardized betas
- Threshold: non-unanimous attacked = flip
- Bayesian: gt-relative log-odds
"""
import os, sys
os.environ["HF_HOME"] = "/root/autodl-tmp/.hf_cache"
sys.path.insert(0, "/root/cert_manip_resist_eval")
sys.stdout.reconfigure(line_buffering=True)

import json, itertools, math
import numpy as np
import statsmodels.api as sm
from pathlib import Path

from src.unified_data_loader import (
    ALL_MODELS, DATASETS, ATTACKS,
    load_all_scores, load_pairs, load_mi_data,
    compute_clean_accuracy,
)

EPS = 1e-6
B = 9999
SEED = 42
METHODS = ["majority_vote", "weighted_vote", "threshold_unanimous", "bayesian"]

def _json_default(obj):
    if isinstance(obj, np.floating):
        v = float(obj); return None if (np.isnan(v) or np.isinf(v)) else v
    if isinstance(obj, np.integer): return int(obj)
    if isinstance(obj, np.ndarray): return obj.tolist()
    if isinstance(obj, np.bool_): return bool(obj)
    raise TypeError(f"Not JSON serializable: {type(obj)}")

def _is_valid_score(score):
    if score is None: return False
    if isinstance(score, dict):
        return score.get("winner") is not None and not score.get("error")
    return False

def majority_vote(votes):
    counts = {"A": 0, "B": 0, "tie": 0}
    for v in votes: counts[v] = counts.get(v, 0) + 1
    mc = max(counts.values())
    winners = [k for k, c in counts.items() if c == mc]
    if len(winners) == 1: return winners[0]
    for w in winners:
        if w != "tie": return w
    return "tie"

def compute_panel_asr_all(jids, clean, attacked, pairs, accs):
    n = min(len(pairs), *(len(clean[j]) for j in jids), *(len(attacked[j]) for j in jids))
    mv_f = mv_c = wv_f = wv_c = th_f = th_d = by_f = by_c = 0
    for i in range(n):
        bad = False
        for j in jids:
            if not _is_valid_score(clean[j][i]) or not _is_valid_score(attacked[j][i]):
                bad = True; break
        if bad: continue
        gt = pairs[i]["ground_truth_winner"]
        cv = [clean[j][i]["winner"] for j in jids]
        av = [attacked[j][i]["winner"] for j in jids]
        # Majority
        mc = majority_vote(cv)
        if mc == gt:
            mv_c += 1
            if majority_vote(av) != gt: mv_f += 1
        # Weighted
        wac = sum(a for v, a in zip(cv, accs) if v == "A")
        wbc = sum(a for v, a in zip(cv, accs) if v == "B")
        cw = "A" if wac > wbc else ("B" if wbc > wac else "tie")
        if cw == gt:
            wv_c += 1
            waa = sum(a for v, a in zip(av, accs) if v == "A")
            wba = sum(a for v, a in zip(av, accs) if v == "B")
            aw = "A" if waa > wba else ("B" if wba > waa else "tie")
            if aw != gt: wv_f += 1
        # Threshold
        if cv[0] == cv[1] == cv[2] == gt:
            th_d += 1
            if not (av[0] == av[1] == av[2] == gt): th_f += 1
        # Bayesian (gt-relative log-odds)
        loc = 0.0
        for v, ac in zip(cv, accs):
            ac = max(min(ac, 0.999), 0.001)
            loc += math.log(ac / (1 - ac)) if v == gt else math.log((1 - ac) / ac)
        if loc > 0:
            by_c += 1
            loa = 0.0
            for v, ac in zip(av, accs):
                ac = max(min(ac, 0.999), 0.001)
                loa += math.log(ac / (1 - ac)) if v == gt else math.log((1 - ac) / ac)
            if loa <= 0: by_f += 1
    return {
        "majority_vote": (mv_f / max(mv_c, 1), mv_c),
        "weighted_vote": (wv_f / max(wv_c, 1), wv_c),
        "threshold_unanimous": (th_f / max(th_d, 1), th_d),
        "bayesian": (by_f / max(by_c, 1), by_c),
    }

def fit_r2(y, x1, x2):
    if np.std(y) < 1e-10 or np.std(x1) < 1e-10: return np.nan
    x1s = (x1 - x1.mean()) / x1.std()
    x2s = (x2 - x2.mean()) / x2.std()
    X = sm.add_constant(np.column_stack([x1s, x2s]))
    try: return float(sm.OLS(y, X).fit().rsquared)
    except: return np.nan

def main():
    print("Loading data...")
    mi_data = load_mi_data(); pairs = load_pairs()
    clean, attacked = load_all_scores()
    clean_acc = compute_clean_accuracy(clean, pairs)

    ind_asr = {}
    for ds in DATASETS:
        for atk in ATTACKS:
            for mid in ALL_MODELS:
                if mid in clean[ds] and mid in attacked[ds][atk]:
                    cl, at = clean[ds][mid], attacked[ds][atk][mid]
                    n = min(len(cl), len(at), len(pairs[ds]))
                    nf = nc = 0
                    for i in range(n):
                        if not _is_valid_score(cl[i]) or not _is_valid_score(at[i]): continue
                        gt = pairs[ds][i]["ground_truth_winner"]
                        if cl[i]["winner"] == gt:
                            nc += 1
                            if at[i]["winner"] != gt: nf += 1
                    ind_asr[(ds, atk, mid)] = nf / max(nc, 1)

    combos = list(itertools.combinations(range(len(ALL_MODELS)), 3))
    nP = len(combos)
    print(f"Panels: {nP}")
    conds = [(ds, atk) for ds in DATASETS for atk in ATTACKS]

    print("Precomputing...")
    pre = {m: {} for m in METHODS}
    for ds, atk in conds:
        cond = f"{ds}x{atk}"
        kd = mi_data["keff_per_panel"].get(ds, {})
        masrs = {m: [] for m in METHODS}; ks = []; es = []
        for combo in combos:
            jids = [ALL_MODELS[i] for i in combo]
            if not all((ds, atk, j) in ind_asr for j in jids): continue
            pk = "|".join(jids)
            if pk not in kd: continue
            accs = [clean_acc.get((j, ds), 0.5) for j in jids]
            r = compute_panel_asr_all(jids, clean[ds], attacked[ds][atk], pairs[ds], accs)
            for m in METHODS:
                asr, denom = r[m]
                masrs[m].append(np.nan if m == "threshold_unanimous" and denom == 0 else asr)
            ks.append(kd[pk]["keff"])
            es.append(max(ind_asr[(ds, atk, j)] for j in jids))
        ka, ea = np.array(ks), np.array(es)
        for m in METHODS:
            a = np.array(masrs[m]); v = ~np.isnan(a)
            pre[m][cond] = {"asr": a[v], "keff": ka[v], "eta": ea[v]}

    for m in METHODS:
        r2s = []
        for ds, atk in conds:
            d = pre[m][f"{ds}x{atk}"]
            if len(d["asr"]) < 10: continue
            r = fit_r2(np.log(d["asr"]+EPS), np.log(d["keff"]), np.log(d["eta"]+EPS))
            if not np.isnan(r): r2s.append(r)
        print(f"  {m}: mean R² = {np.mean(r2s):.4f} ({len(r2s)} conds)")

    print(f"\nBootstrap B={B}...")
    rng = np.random.RandomState(SEED)
    br2 = {m: [] for m in METHODS}
    for b in range(B):
        if (b+1) % 1000 == 0: print(f"  {b+1}/{B}")
        for m in METHODS:
            cr = []
            for ds, atk in conds:
                d = pre[m][f"{ds}x{atk}"]
                n = len(d["asr"])
                if n < 10: continue
                idx = rng.randint(0, n, size=n)
                r = fit_r2(np.log(d["asr"][idx]+EPS), np.log(d["keff"][idx]), np.log(d["eta"][idx]+EPS))
                if not np.isnan(r): cr.append(r)
            if cr: br2[m].append(np.mean(cr))

    out = {"B": B, "seed": SEED, "EPS": EPS, "n_panels": nP, "methods": {}}
    for m in METHODS:
        br = np.array(br2[m])
        r2o = []
        for ds, atk in conds:
            d = pre[m][f"{ds}x{atk}"]
            if len(d["asr"]) < 10: continue
            r = fit_r2(np.log(d["asr"]+EPS), np.log(d["keff"]), np.log(d["eta"]+EPS))
            if not np.isnan(r): r2o.append(r)
        out["methods"][m] = {
            "R2_original": float(np.mean(r2o)),
            "R2_bootstrap_mean": float(np.mean(br)),
            "R2_ci_lower": float(np.percentile(br, 2.5)),
            "R2_ci_upper": float(np.percentile(br, 97.5)),
            "R2_bootstrap_std": float(np.std(br)),
            "n_valid_conditions": len(r2o), "n_bootstrap": len(br),
        }

    pw = {}
    for i in range(len(METHODS)):
        for j in range(i+1, len(METHODS)):
            m1, m2 = METHODS[i], METHODS[j]
            b1, b2 = np.array(br2[m1]), np.array(br2[m2])
            nm = min(len(b1), len(b2)); d = b1[:nm] - b2[:nm]
            pw[f"{m1}_minus_{m2}"] = {
                "diff_mean": float(np.mean(d)), "diff_ci_lower": float(np.percentile(d, 2.5)),
                "diff_ci_upper": float(np.percentile(d, 97.5)), "prob_positive": float(np.mean(d > 0)),
            }
    out["pairwise_differences"] = pw

    op = Path("/root/cert_manip_resist_eval/artifacts/results/plan001/aggregation_r2_bootstrap.json")
    with open(op, "w") as f: json.dump(out, f, indent=2, default=_json_default)
    print(f"\nSaved: {op}")
    print("\n" + "="*80)
    for m in METHODS:
        r = out["methods"][m]
        print(f"  {m:<24} R²={r['R2_original']:.4f}  boot={r['R2_bootstrap_mean']:.4f}  "
              f"95% CI=[{r['R2_ci_lower']:.4f}, {r['R2_ci_upper']:.4f}]")
    print("\nPairwise:")
    for k, v in pw.items():
        print(f"  {k:<55} diff={v['diff_mean']:+.4f}  "
              f"CI=[{v['diff_ci_lower']:+.4f}, {v['diff_ci_upper']:+.4f}]  P(>0)={v['prob_positive']:.3f}")

if __name__ == "__main__":
    main()
